const input = $input.first().json;
const body = input.body ?? input;
const order_number = String(body.order_number ?? '').trim().toUpperCase();
const order_status = String(body.order_status ?? '').trim();
const allowed = ['Order received','Preparing','On the way','Delivered','Cancelled'];
if (!order_number) throw new Error('order_number is required');
if (!allowed.includes(order_status)) throw new Error('Invalid order_status');
const to = String(body.customer_email ?? '');
const subject = order_status === 'Cancelled' ? `FilipinOnly order ${order_number} was cancelled` : `FilipinOnly order ${order_number} is ${order_status}`;
const message = order_status === 'Delivered' ? 'Your order has been delivered. Thank you for ordering with FilipinOnly.' : order_status === 'Cancelled' ? 'Your order was cancelled. Contact the store if you need help.' : `Your order is now ${order_status}. We will keep you updated.`;
const html = `<div style="font-family:Arial,sans-serif;line-height:1.5"><h2>Order ${order_number}</h2><p>${message}</p><p><strong>Status:</strong> ${order_status}</p></div>`;
return [{ json: { ok: true, message: 'Status notification prepared from MySQL order data.', order_number, order_status, email: { to, subject, html } } }];
